# - Minimal S3/E1-E3 (not viable yet)

targeted_spend = {
  'social_media': {
    'S1': 600,      # Strong channel for S1
    'S2': 75,       # Light test
  },
  'search_ads': {
    'S1': 400,      # Secondary channel for S1
